import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p39_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor l2norm_forward(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("l2norm_forward", &l2norm_forward, "Fused L2 normalization (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Fused L2 normalization kernel: one block per row, warp+shared reduction
__global__ void l2norm_kernel(const float* __restrict__ x,
                               float* __restrict__ y,
                               int N, int C) {
    int row = blockIdx.x;
    if (row >= N) return;

    const float* row_x = x + (long long)row * C;
    float* row_y = y + (long long)row * C;

    // Phase 1: accumulate sum of squares
    float local_sum = 0.0f;
    for (int col = threadIdx.x; col < C; col += blockDim.x) {
        float v = row_x[col];
        local_sum += v * v;
    }

    // Warp reduction
    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1)
        local_sum += __shfl_down_sync(mask, local_sum, offset);

    // Block reduction via shared memory
    extern __shared__ float sdata[];
    int lane = threadIdx.x & 31;
    int wid  = threadIdx.x >> 5;
    if (lane == 0) sdata[wid] = local_sum;
    __syncthreads();

    int num_warps = (blockDim.x + 31) >> 5;
    float block_sum = (threadIdx.x < num_warps) ? sdata[threadIdx.x] : 0.0f;
    if (threadIdx.x < 32) {
        for (int offset = 16; offset > 0; offset >>= 1)
            block_sum += __shfl_down_sync(mask, block_sum, offset);
        if (threadIdx.x == 0) sdata[0] = block_sum;
    }
    __syncthreads();

    float inv_norm = rsqrtf(sdata[0] + 1e-12f);

    // Phase 2: normalize
    for (int col = threadIdx.x; col < C; col += blockDim.x) {
        row_y[col] = row_x[col] * inv_norm;
    }
}

torch::Tensor l2norm_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int N = x.size(0);
    int C = x.size(1);

    auto y = torch::empty_like(x);

    int block_size = 256;
    int num_warps = (block_size + 31) / 32;
    int smem = num_warps * sizeof(float);

    dim3 grid(N);
    dim3 block(block_size);

    l2norm_kernel<<<grid, block, smem>>>(
        x.data_ptr<float>(),
        y.data_ptr<float>(),
        N, C
    );

    return y;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs L2 normalization.
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the L2Norm layer.

                Args:
                    dim (int): Dimension along which to normalize.
                """
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        use_cuda_fastpath = x.is_cuda and x.dtype == torch.float32 and x.is_contiguous() and x.dim() == 2
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if use_cuda_fastpath:
            return _stark_get_extension().l2norm_forward(x)
        return x / torch.norm(x, p=2, dim=1, keepdim=True)
        # <<<END_IMPROVE>>>

